const LANG_LIST = Object.keys(LANGS)
let CURRENT = 'en'

function lookupDict(dict, path) {
  let o = dict
  for (const part of path.split('.')) {
    if (o == null || !(part in o)) return undefined
    o = o[part]
  }
  return typeof o === 'string' ? o : undefined
}

function t(key, vars) {
  let s = lookupDict(LANGS[CURRENT], key)
  if (s == null) s = lookupDict(LANGS.en, key)
  if (s == null) return key
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      s = s.split('{' + k + '}').join(String(v == null ? '' : v))
    }
  }
  return s
}

function getLang() {
  return CURRENT
}

function setLang(code) {
  CURRENT = LANGS[code] ? code : 'en'
}

function applyLang(code) {
  setLang(code)
  const L = LANGS[CURRENT]
  document.documentElement.lang = CURRENT
  document.documentElement.dir = L.dir
  document.querySelectorAll('[data-i18n]').forEach((el) => {
    el.textContent = t(el.dataset.i18n)
  })
  document.querySelectorAll('[data-i18n-ph]').forEach((el) => {
    el.placeholder = t(el.dataset.i18nPh)
  })
  document.querySelectorAll('[data-i18n-title]').forEach((el) => {
    el.title = t(el.dataset.i18nTitle)
  })
  if (typeof state !== 'undefined' && state.config) state.config.lang = CURRENT
  if (typeof renderAll === 'function') renderAll()
}

