function tJobLabel(label) {
  if (!label) return label
  const src = JOB_LABELS.ar
  const dst = JOB_LABELS[CURRENT] || JOB_LABELS.en
  const ordered = Object.keys(src).sort((a, b) => src[b].split('{')[0].length - src[a].split('{')[0].length)
  for (const key of ordered) {
    const parts = src[key].split(/\{[^}]+\}/)
    const vars = [...src[key].matchAll(/\{([^}]+)\}/g)].map((x) => x[1])
    const esc = (p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp('^' + parts.map(esc).join('(.*)') + '$')
    const m = label.match(re)
    if (m) {
      let out = dst[key]
      vars.forEach((v, i) => { out = out.split('{' + v + '}').join(m[i + 1] || '') })
      return out
    }
  }
  return label
}

const SERVER_EXACT = {
  ar: { 'اختر إصدار فابريك': 'fabricChoose', 'اختر إصدار فورج': 'forgeChoose' }
}

function tServer(msg) {
  if (!msg) return msg
  if (SERVER_EXACT.ar[msg]) return (JOB_LABELS[CURRENT] || JOB_LABELS.en)[SERVER_EXACT.ar[msg]] || msg
  const src = LANGS.ar.server
  const dst = (LANGS[CURRENT] && LANGS[CURRENT].server) || LANGS.en.server
  for (const key of Object.keys(src)) {
    const parts = src[key].split(/\{[^}]+\}/)
    const vars = [...src[key].matchAll(/\{([^}]+)\}/g)].map((x) => x[1])
    const esc = (p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp('^' + parts.map(esc).join('(.*)') + '$')
    const m = msg.match(re)
    if (m) {
      let out = dst[key]
      vars.forEach((v, i) => { out = out.split('{' + v + '}').join(m[i + 1] || '') })
      return out
    }
  }
  return msg
}
